import {advance,summarize,validateOrThrow} from './engine.mjs';
let running=false;
self.onmessage=async({data})=>{if(data.type!=='simulate'||running)return;running=true;try{let state=validateOrThrow(data.state),remaining=data.seconds,total=remaining,processed=0;const before=summarize(state);if(!Number.isFinite(total)||total<0)throw Error('離線時間無效');let sinceYield=performance.now();while(remaining>0){const chunk=Math.min(remaining,300);advance(state,chunk,{offline:true});processed+=chunk;remaining=Math.max(0,total-processed);if(performance.now()-sinceYield>180){self.postMessage({type:'checkpoint',state,processed,total});await new Promise(r=>setTimeout(r,0));sinceYield=performance.now()}}self.postMessage({type:'done',state,processed,total,before,after:summarize(state)})}catch(e){self.postMessage({type:'error',message:e.message})}finally{running=false}};
